def check(rows):
    if len(rows) != 18 or any(len(row) != 8 for row in rows): return False, "shape"
    if any(type(x) is not int or not 0 <= x < 6 for row in rows for x in row): return False, "alphabet"
    for i,j in combinations(range(18),2):
        if sum(a == b for a,b in zip(rows[i],rows[j])) > 1: return False, "row_agreement"
    for c,d in combinations(range(8),2):
        events=[(row[c],row[d]) for row in rows]
        if len(set(events)) != 18: return False, "column_pair_duplicate"
    return True, "PASS"
